enum WeaponStatus
{
	READY_TO_FIRE = 0,
	OUT_OF_AMMO = 1,
	BETWEEN_FIRING_SHOTS = 2
};

class Weapon
{
public:
	bool privateFireWeapon(const Object *source, const Coord3D *sourcePos,
		const Object *victim, int victimId, const Coord3D *victimPos,
		int isDetonation, int ignoreRanges, int extraBonusFlags,
		int *projectileID);

	WeaponStatus bfmeComputeStatus(bool *valid) const;
	void computeBonus(const Object *source, unsigned extra, WeaponBonus &bonus) const;
	void processRequestAssistance(const Object *source, const Object *victim);
	void reloadAmmo(const Object *source);
	unsigned getRemainingAmmo(bool countReloadingAsEmpty) const;

	void *m_vptr;
	WeaponTemplate *m_template;
	int m_sourceId;
	int m_wslot;
	unsigned m_status;
	unsigned m_ammoInClip;
	unsigned m_whenWeCanFireAgain;
	unsigned m_whenPreAttackFinished;
	unsigned m_whenLastReloadStarted;
	unsigned m_lastFireFrame;
	unsigned m_projectileStreamID;
	unsigned m_lastFireStamp;
	unsigned m_suspendFXFrame;
	int m_maxShotCount;
	int m_curBarrel;
	int m_numShotsForCurBarrel;
	int *m_scatterBegin;
	int *m_scatterEnd;
	int *m_scatterCap;
	unsigned char m_pitchLimited;
	unsigned char m_pad4d[3];
	unsigned m_leechWeaponRangeActive;
	unsigned m_linearIndex;
	unsigned m_tail;
};

extern GameLogic *TheGameLogic;
extern TerrainLogic *TheTerrainLogic;
extern float g_bfmeZeroCY;

int GetGameLogicRandomValue(int low, int high, char *file, int line);

#include "0x001e49e0.cpp"

// ?privateFireWeapon@Weapon@@QAE_NPBVObject@@PBUCoord3D@@0H1HHHPAH@Z
bool Weapon::privateFireWeapon(const Object *source, const Coord3D *sourcePos,
	const Object *victim, int victimId, const Coord3D *victimPos,
	int isDetonation, int ignoreRanges, int extraBonusFlags,
	int *projectileID)
{
	WeaponBonus bonus;
	computeBonus(source, (unsigned)extraBonusFlags, bonus);

	if (projectileID)
		*projectileID = 0;

	if (!this->m_template)
		return false;

	if (this->m_template->m_requestAssistRange != g_bfmeZeroCY && victim)
		this->processRequestAssistance(source, victim);

	if (this->m_template->m_isLeechRangeWeapon)
	{
		int timing = (int)(float)this->m_template->m_timingExtra;
		int one = 1;
		int *add = timing < 1 ? &one : &timing;
		this->m_leechWeaponRangeActive = TheGameLogic->getFrame() + *add;
	}

	{
		bool cacheOk = true;
		WeaponStatus st = this->bfmeComputeStatus(&cacheOk);
		if (cacheOk && this->m_status != (unsigned)st)
			this->m_status = (unsigned)st;
		if (st != READY_TO_FIRE)
			return false;
	}

	unsigned now = TheGameLogic->getFrame();
	bool reloaded = false;
	int delay = this->m_template->getDelayBetweenShots(bonus);

	if (this->m_template->m_filter.isValid())
	{
		Object *srcObj = TheGameLogic->findObjectByID(this->m_sourceId);
		FilterSink *sink = srcObj ? srcObj->m_filterSink : 0;
		if (sink)
			sink->apply(&this->m_template->m_filter);
	}

	if (this->m_ammoInClip == 0)
		return reloaded;

	{
		int barrels = source->getDrawable()->getBarrelCount(this->m_wslot);
		if (this->m_curBarrel >= barrels)
		{
			this->m_curBarrel = 0;
			this->m_numShotsForCurBarrel = this->m_template->m_shotsPerBarrel;
		}
	}

	if (isDetonation)
	{
		this->m_template->bfmeTellLO(this, source, victim, &bonus);
	}
	else if (this->m_template->m_linearTargets.m_end != this->m_template->m_linearTargets.m_begin)
	{
		int n = (int)(this->m_template->m_linearTargets.m_end
			- this->m_template->m_linearTargets.m_begin) / 12;
		int i = 0;
		while (i < n)
		{
			rva001E49E0Aim(&this->m_template->m_linearTargets,
				(int)this->m_linearIndex, source, (Coord3D *)&bonus);
			if (!this->m_template->m_linearGate || this->m_linearIndex)
			{
				this->m_template->fireWeaponTemplate(
					source, sourcePos, this->m_wslot, this->m_curBarrel,
					victim, victimId, (Coord3D *)&bonus, bonus, isDetonation, this, projectileID);
			}
			int flag = ((int *)(this->m_template->m_linearTargets.m_begin
				+ this->m_linearIndex * 12))[2];
			this->m_linearIndex = (this->m_linearIndex + 1) % n;
			if (flag)
				break;
			++i;
		}
	}
	else if (this->m_scatterEnd - this->m_scatterBegin)
	{
		const Coord3D *pos = victimPos;
		if (victim)
		{
			pos = &victim->m_position;
			victim = 0;
		}
		*(Coord3D *)&bonus = *pos;
		int pick = GetGameLogicRandomValue(
			0,
			(int)(this->m_scatterEnd - this->m_scatterBegin) - 1,
			"F:\\bfme\\Code\\gameengine\\Source\\GameLogic\\Object\\Weapon.cpp",
			2915);
		int index = this->m_scatterBegin[pick];
		float scalar = this->m_template->m_scatterScalar;
		Coord2D off = this->m_template->m_scatterTargets.m_begin[index];
		((Coord3D *)&bonus)->x += off.x * scalar;
		((Coord3D *)&bonus)->y += off.y * scalar;
		((Coord3D *)&bonus)->z = TheTerrainLogic->getGroundHeight(((Coord3D *)&bonus)->x, ((Coord3D *)&bonus)->y, 0);
		this->m_scatterBegin[pick] = this->m_scatterEnd[-1];
		--this->m_scatterEnd;
		this->m_template->fireWeaponTemplate(
			source, sourcePos, this->m_wslot, this->m_curBarrel,
			victim, victimId, (Coord3D *)&bonus, bonus, isDetonation, this, projectileID);
	}
	else
	{
		this->m_template->fireWeaponTemplate(
			source, sourcePos, this->m_wslot, this->m_curBarrel,
			victim, victimId, victimPos, bonus, isDetonation, this, projectileID);
	}

	--this->m_ammoInClip;
	--this->m_maxShotCount;
	--this->m_numShotsForCurBarrel;
	this->m_lastFireStamp = now;
	if (this->m_numShotsForCurBarrel <= 0)
	{
		++this->m_curBarrel;
		this->m_numShotsForCurBarrel = this->m_template->m_shotsPerBarrel;
	}

	if (this->getRemainingAmmo(false) == 0)
	{
		if (this->m_template->m_reloadType == 0)
		{
			this->reloadAmmo(source);
			reloaded = true;
			return reloaded;
		}
		if (this->m_status != OUT_OF_AMMO)
			this->m_status = OUT_OF_AMMO;
		if (!this->m_template->m_filter.isValid())
			this->m_whenWeCanFireAgain = 0x7fffffff;
		return reloaded;
	}

	if (this->m_status != BETWEEN_FIRING_SHOTS)
		this->m_status = BETWEEN_FIRING_SHOTS;
	this->m_whenWeCanFireAgain = now + (unsigned)delay;
	this->m_projectileStreamID = now;

	WeaponSet *ws = (WeaponSet *)((char *)source + 0x264);
	if (ws->isReloadTimeShared())
	{
		for (int slot = 0; slot < 4; ++slot)
		{
			Weapon *w = ws->getWeaponInWeaponSlot(slot);
			if (w)
			{
				w->m_whenWeCanFireAgain = this->m_whenWeCanFireAgain;
				if (w->m_status != BETWEEN_FIRING_SHOTS)
					w->m_status = BETWEEN_FIRING_SHOTS;
			}
		}
	}

	int extraTime = (int)(float)m_template->m_timingExtra;
	if (extraTime > 0)
		this->m_whenLastReloadStarted = TheGameLogic->getFrame() + (unsigned)extraTime;

	return reloaded;
}
